python3 - <<'EOF'
import json,subprocess,time,urllib.request
def tok(): return subprocess.check_output(['python3','/tmp/tok.py']).decode().strip()
url="https://run.googleapis.com/v2/projects/redu-425516/locations/us-central1/services/umami-acs1c2aa298"
for i in range(60):
    r=urllib.request.Request(url,headers={'Authorization':'[REDACTED:value]'+tok()})
    d=json.load(urllib.request.urlopen(r))
    conds={c['type']:c['state'] for c in d.get('conditions',[])}
    print(time.strftime('%T'),d.get('uri'),conds, d.get('latestReadyRevision','').split('/')[-1])
    if d.get('uri') and d.get('latestReadyRevision') and conds.get('Ready')=='CONDITION_SUCCEEDED':
        break
    if conds.get('Ready')=='CONDITION_FAILED':
        print(json.dumps(d.get('conditions'),indent=1)); break
    time.sleep(8)
EOF
